import { useState } from "react";

// Logic THUẦN tách khỏi giao diện: kiểm thử cực dễ, không cần render
export function applyDiscount(total, code) {
  if (code === "SALE10") return Math.round(total * 0.9);
  return total;
}

export default function App() {
  const [total] = useState(200);
  const [code, setCode] = useState("");
  return (
    <div>
      <input id="code" aria-label="Mã giảm giá" value={code} onChange={(e) => setCode(e.target.value)} />
      <p id="total" data-testid="total">{applyDiscount(total, code)}</p>
    </div>
  );
}

