import { useState } from "react";

const applyDiscount = (total, code) => (code === "SALE10" ? Math.round(total * 0.9) : total);

export default function App() {
  const [code, setCode] = useState("");
  return (
    <div>
      <input aria-label="Mã giảm giá" value={code} onChange={(e) => setCode(e.target.value)} />
      <p data-testid="total">{applyDiscount(200, code)}</p>
    </div>
  );
}
